/// Desktop's mark for app `id` (`AppIcon`'s ids: "vscode", "file-explorer", ...), in the
/// variant for a dark or light appearance; None for the marks Desktop draws from PNGs.
pub fn named(id: &str, dark: bool) -> Option<&'static Icon> {
    Some(match id {
        "zed" if dark => &ZED_DARK,
        "vscode" => &VSCODE,
        "cursor" => &CURSOR,
        "zed" => &ZED,
        "file-explorer" => &FILE_EXPLORER,
        "iterm2" => &ITERM2,
        "ghostty" => &GHOSTTY,
        "android-studio" => &ANDROID_STUDIO,
        "antigravity" => &ANTIGRAVITY,
        "powershell" => &POWERSHELL,
        "sublime-text" => &SUBLIME_TEXT,
        _ => return None,
    })
}
